import java.util.*;
class SortWeight
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        double weight[] = new double[10];
        System.out.println("Enter the weight of 10 people:");
        for (int i = 0; i < 10; i++)
            weight[i] = sc.nextDouble();
        // selection sort: put the largest remaining weight at position i
        for (int i = 0; i < 9; i++)
        {
            int pos = i;
            for (int j = i + 1; j < 10; j++)
            {
                if (weight[j] > weight[pos])
                    pos = j;
            }
            double t = weight[i];
            weight[i] = weight[pos];
            weight[pos] = t;
        }
        System.out.println("Weights in descending order:");
        for (int i = 0; i < 10; i++)
            System.out.println(weight[i]);
    }
}

/* Variable description
   weight[] - double array of 10 weights
   i, j - loop variables
   pos - index of the largest element in the unsorted part
   t - temporary variable for swapping
*/

