questions.solution:
class MergeAlternate
{
    public static void main(String args[])
    {
        int x[] = {5, -3, -2, 1, 0, 12, 14, 16, 25, 13};
        int y[] = {6, 5, 10, 15, 18, 20, 22, 30};
        int z[] = new int[18];
        int k = 0;
        for (int i = 0; i < 8; i++)     // take x and y alternately
        {
            z[k] = x[i];
            k++;
            z[k] = y[i];
            k++;
        }
        z[16] = x[8];                   // remaining elements of x
        z[17] = x[9];
        for (int i = 0; i < 18; i++)
            System.out.print(z[i] + " ");
    }
}

