import java.util.*;
class BinarySearch
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        int arr[] = new int[5];
        System.out.println("Enter 5 numbers in ascending order:");
        for (int i = 0; i < 5; i++)
            arr[i] = sc.nextInt();
        System.out.println("Enter the number to search:");
        int value = sc.nextInt();
        int lb = 0, ub = 4, pos = -1;
        while (lb <= ub)
        {
            int mid = (lb + ub) / 2;
            if (arr[mid] == value)
            {
                pos = mid;
                break;
            }
            else if (value < arr[mid])
                ub = mid - 1;
            else
                lb = mid + 1;
        }
        if (pos == -1)
            System.out.println("Value not found");
        else
            System.out.println("Position is: " + (pos + 1));
    }
}

/* Variable description
   arr[] - 5 integers in ascending order
   value - number to search
   lb, ub, mid - lower bound, upper bound and middle index
   pos - index where found (-1 if not found)
   i - loop variable
*/

