            }
            avg[i] = tot / t;
            classTotal = classTotal + avg[i];
        }
        for (int i = 0; i < n; i++)
            System.out.println("Average score of " + name[i] + " = " + avg[i]);
        System.out.println("Class average = " + (classTotal / n));
    }
}

/* Variable description
   n - number of students
   t - number of tests
   name[] - names of the students
   avg[] - average score of each student
   tot - total score of one student
   classTotal - sum of all student averages
   i, j - loop variables
*/

(Note: the source program divided the sum of all scores by the number of students only, which gives an average total rather than an average test score; dividing the sum of the student averages by n, as here, gives the class average on the same scale as each student's average.)

