import java.util.*;
class IdentityMatrix
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        int n[][] = new int[5][5];
        System.out.println("Enter the 25 elements of the matrix row by row:");
        for (int i = 0; i < 5; i++)
            for (int j = 0; j < 5; j++)
                n[i][j] = sc.nextInt();
        boolean identity = true;
        for (int i = 0; i < 5; i++)
        {
            for (int j = 0; j < 5; j++)
            {
                if (i == j && n[i][j] != 1)
                    identity = false;      // a diagonal element is not 1
                else if (i != j && n[i][j] != 0)
                    identity = false;      // an off-diagonal element is not 0
            }
        }
        if (identity)
            System.out.println("Identity matrix");
        else
            System.out.println("Not an identity matrix");
    }
}

/* Variable description
   n[][] - 5 x 5 matrix
   identity - stays true only if every element fits the rule
   i, j - row and column loop variables
